#define _POSIX_C_SOURCE 200809L
// The XSI level of the same edition, beside it. sigaltstack is XSI. It gives a crash report a
// stack to run on once the program's own has run out (hosted.c's "A crash says what happened").
// The bare POSIX level hides XSI on glibc and musl. Windows has neither level.
#if !defined(_WIN32)
#define _XOPEN_SOURCE 700
#endif
// Caution: **On macOS, always raise _DARWIN_C_SOURCE too.** Apple's headers hide "what is not in
// POSIX.1" where `_POSIX_C_SOURCE` is defined. What hides includes sysconf's _SC_NPROCESSORS_ONLN
// (an extension) and even the BSD type aliases <sys/*.h> uses internally (u_int / u_char /
// u_short). Define nothing, and macOS's default is the equivalent of _DARWIN_C_SOURCE. So this is
// the setting that "goes back to the default" (only the declarations multiply; the ABI does
// not change).
// Caution: **Place it ahead of the includes.** Defined afterwards, it does not take effect. The
// include guards of the headers already read are raised.
// glibc publishes these unconditionally, so **dropping it passes on Linux and surfaces on
// macOS alone**.
#if defined(__APPLE__)
#define _DARWIN_C_SOURCE
#endif
// The oldest Windows the runtime is written for is Windows 10, whose C runtime is UCRT. State it
// rather than take the headers' default, which differs per SDK. An older MinGW's is Windows 7,
// and it hides GetCurrentThreadStackLimits (Windows 8) from kspl_stack_floor.
// Caution: **Raise WINVER with it**: some headers gate on WINVER alone. A higher one given with
// -D stays, as the headers then only declare more.
#if defined(_WIN32) && (!defined(_WIN32_WINNT) || _WIN32_WINNT < 0x0A00)
#undef _WIN32_WINNT
#define _WIN32_WINNT 0x0A00
#endif
#if defined(_WIN32) && (!defined(WINVER) || WINVER < 0x0A00)
#undef WINVER
#define WINVER 0x0A00
#endif
#include <stdarg.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
// The premise for std/rand.kspl's CSPRNG (kspl_rand_fill, hosted.c) using rand_s() on Windows.
// #defined after stdlib.h, it is ignored by the header guard (where that has already been
// included). So it must be defined ahead of here (stdlib.h's first include), without fail. On
// POSIX/macOS it is an unrelated macro name and harmless.
#define _CRT_RAND_S
#include <math.h>
#include <signal.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#if !defined(_WIN32)
/* The four below stand here because they name sigaction's handler fields and siginfo's address,
   names the list below removes. A signal is taken only where it is at its default: a handler
   already set (a sanitizer's, the host program's) is left alone. */
__attribute__((unused)) static int kspl_signal_at_default(int sig) {
  struct sigaction old;
  if (sigaction(sig, NULL, &old) != 0)
    return 0;
  return (old.sa_flags & SA_SIGINFO) == 0 && old.sa_handler == SIG_DFL;
}

/* Puts handler on sig (for hosted_proc.c's groups). */
__attribute__((unused)) static void kspl_take_default_signal(int sig, void (*handler)(int)) {
  struct sigaction sa;
  if (!kspl_signal_at_default(sig))
    return;
  memset(&sa, 0, sizeof(sa));
  sa.sa_handler = handler;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = SA_RESTART;
  (void)sigaction(sig, &sa, NULL);
}

/* Puts action on a fault, run on the alternate stack (hosted.c's crash section); 1 where taken. */
__attribute__((unused)) static int kspl_take_default_fault(int sig,
                                                           void (*action)(int, siginfo_t *, void *)) {
  struct sigaction sa;
  if (!kspl_signal_at_default(sig))
    return 0;
  memset(&sa, 0, sizeof(sa));
  sa.sa_sigaction = action;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
  return sigaction(sig, &sa, NULL) == 0;
}

/* The address a fault names. */
__attribute__((unused)) static uintptr_t kspl_fault_addr(const siginfo_t *info) {
  return (uintptr_t)info->si_addr;
}
#endif

/* These are object-like macros the headers above `#define`, of the same names as KSPL's
   identifiers. Unremoved, they are expanded at the positions that come out bare (a local
   variable, a formal parameter, a struct field) and become a C compiler error. The runtime reads
   none of them, but for the four functions above.
   Caution: The names removed differ per target: si_* / sa_* / sigev_* come from POSIX's
   <signal.h>, and environ / popen / strcasecmp / sys_errlist and the like from Windows's CRT.
   An #undef of an undefined macro is correct C, so both lists can stay and pass on either
   target. */
#undef L_ctermid
#undef L_tmpnam
#undef P_tmpdir
#undef environ
#undef math_errhandling
#undef matherr
#undef onexit_t
#undef pclose
#undef popen
#undef sa_handler
#undef sa_sigaction
#undef si_addr
#undef si_addr_lsb
#undef si_arch
#undef si_band
#undef si_call_addr
#undef si_fd
#undef si_int
#undef si_lower
#undef si_overrun
#undef si_pid
#undef si_pkey
#undef si_ptr
#undef si_status
#undef si_stime
#undef si_syscall
#undef si_timerid
#undef si_uid
#undef si_upper
#undef si_utime
#undef si_value
#undef sigev_notify_attributes
#undef sigev_notify_function
#undef strcasecmp
#undef strncasecmp
#undef sys_errlist
#undef sys_nerr
#undef wcswcs
#undef wpopen
/* The "declaration half" of the C runtime's preamble header (common to both targets).
 * **Only macros, typedefs, extern declarations and static inline functions.** This enters every
 * generated unit, so a definition with external linkage would be doubled (it goes in core.c).
 * **The five run-time checks** (`kspl_bounds_check`, `kspl_div_check`, `kspl_sdiv` / `kspl_smod`,
 * `kspl_shift_check`, `kspl_tag_check`) are all below. Each target's header gives only what a
 * breach does. **Signed `/` `%` never go out bare**: a minimum by -1 is undefined in C, so
 * `a / -1` wraps to -a and `a % -1` is 0.
 * **Widths are `int64_t`, not `ptrdiff_t`**: a 32-bit target truncates an `I64`, and a non-zero
 * divisor would read as 0. A shift's `width` is counted at the portable lower bound. The signed
 * pair has a 32-bit twin for types of 32 bits and fewer. Genc picks it by the operand's type.
 * Caution: **Take `file` / `line` in the same order on both sides**: genc puts one call out. */

#if defined(__GNUC__) || defined(__clang__)
#define KSPL_UNUSED __attribute__((unused))
#define KSPL_NORETURN __attribute__((noreturn))
#else
#define KSPL_UNUSED
#define KSPL_NORETURN
#endif

/* The linkage of the runtime's own functions and data. Under `--library` the generated C defines
 * KSPL_LIBRARY before this file. They are then `static`, as is every symbol of the library but an
 * `#export`: each library in a program keeps its own runtime. Elsewhere the word is empty.
 * Caution: **Put it on every declaration and definition of a runtime symbol.** C refuses a `static`
 * definition after a declaration without it (genc writes std's `extern` declarations with it). */
#if defined(KSPL_LIBRARY)
#define KSPL_LINK static KSPL_UNUSED
#else
#define KSPL_LINK
#endif

/* The mark on a function carrying `#export`. On wasm it is `export_name`. In a library built for
 * Windows it is `dllexport`, which a DLL needs to export it. Elsewhere it is empty.
 * Caution: **On wasm it is itself the list of functions exported to the host.** Without it,
 * wasm-ld's `--gc-sections` drops the function, and a forgotten `--export=` passes in silence. */
#if defined(__wasm__)
#define KSPL_EXPORT(name) __attribute__((export_name(#name)))
#elif defined(_WIN32) && defined(KSPL_LIBRARY)
#define KSPL_EXPORT(name) __declspec(dllexport)
#else
#define KSPL_EXPORT(name)
#endif

// `#section("...")`'s output target. ELF takes the name as it is; Mach-O accepts only
// "segment,section", so the segment is filled in (a named section inside the data area).
#if defined(__APPLE__)
#define KSPL_SECTION(name) __attribute__((section("__DATA," name)))
#else
#define KSPL_SECTION(name) __attribute__((section(name)))
#endif

#define null NULL

