const U8 kspl_priv_ksplc_tools_surface_COL = 9;
const U8 kspl_priv_ksplc_tools_surface_PART_MARK = 126;
const Slice_U8 kspl_priv_ksplc_tools_surface_FILE_KEY = KSPL_STR_INIT("~");
const I32 kspl_priv_ksplc_tools_run_FEED_IDLE_MS = 60000;
const Sz kspl_priv_ksplc_tools_run_MAX_RUN_SLOTS = (Sz)64;
const I64 kspl_priv_ksplc_tools_run_RUN_SLOT_SPARE_SECS = 3600LL;
const Slice_U8 kspl_priv_ksplc_tools_run_RUN_CFLAGS = KSPL_STR_INIT("-std=c99");
