const Slice_U8_Const_Array_2 kspl_priv_ksplc_tools_run_RUN_SECTION_FLAGS = {.data = {KSPL_STR_INIT("-ffunction-sections"), KSPL_STR_INIT("-fdata-sections")}};
Option_ksplc_tools_run_Target_kind kspl_priv_ksplc_tools_run_target_answer = {.tag = kspl_Option_ksplc_tools_run_Target_kind_none};
