const Slice_U8 kspl_priv_ksplc_tools_run_EXE_STACK_GNU = KSPL_STR_INIT("-Wl,--stack,8388608");
const Sz kspl_priv_ksplc_tools_run_MAX_RUN_UNITS = (Sz)16;
