int main(int _argc, char **_argv) {
  argc = _argc;
  argv = (uint8_t **)kspl_os_argv(_argc, _argv);
  kspl_io_attach_console();
  kspl_io_init_console();
  kspl_io_set_stdio_binary();
  Result_Void_I32 _res = kspl_main();
  if (_res.tag == kspl_Result_Void_I32_err) {
    int _status = kspl_main_fail(1, (int64_t)_res.payload.err.error, NULL);
    kspl_std_lang_print_trace();
    return _status;
  }
  return 0;
}
typedef char kspl_folded_for_x86_64_linux_gnu_0[(sizeof(Sz) == 8) ? 1 : -1];
